{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — Sound Bath Experience</title>
  <meta name="description" content="Sensory, premium sound bath events and private sessions in {{CITY}}, {{STATE}}. Discover flow, FAQs, and book a VIP day." />
  <link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Crect width='100' height='100' fill='%23FDEFE8'/%3E%3Ccircle cx='50' cy='50' r='36' fill='%23FFD7B5' stroke='%23E6A57A' stroke-width='4'/%3E%3C/svg%3E" />
  <meta name="theme-color" content="#FAF5EF" />
  <link rel="stylesheet" href="assets/css/styles.css" />
</head>
<body class="page-root">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav">
        <a href="events.html">Gatherings</a>
        <a href="private-sessions.html">Sessions</a>
        <a href="pricing.html">Investment</a>
        <a href="about.html">Our Story</a>
        <a href="faq.html">Questions</a>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
      <button class="nav-toggle" aria-label="Open menu">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO: sensory + premium -->
    <section class="hero" style="background-image: url('assets/img/pattern.svg');">
      <div class="wrap hero-inner">
        <div class="hero-copy">
          <h1>Immersive sound therapy for deep presence</h1>
          <p class="lead">A curated sensory journey with live instruments that helps you reset, rest, and return — guided in {{CITY}}, {{STATE}} by {{FACILITATOR_NAME}}.</p>
          <div class="hero-cta">
            <a class="btn primary" href="events.html">Explore Next Event</a>
            <a class="btn ghost" href="book.html">Book a VIP day</a>
          </div>
        </div>
        <div class="hero-panel">
          <div class="panel-top">Next event</div>
          <div class="panel-body">
            <strong class="date">{{NEXT_EVENT_DATE}}</strong>
            <p class="venue">At {{VENUE_NAME}} — limited mats</p>
            <a class="btn small" href="events.html">Reserve a spot</a>
          </div>
        </div>
      </div>
    </section>

    <!-- DIAGNOSTIC: who it's for, contraindications -->
    <section class="diagnostic wrap">
      <h2>Is a sound bath right for you?</h2>
      <p>We blend gongs, chimes, and focused harmonic bowls to create a layered spectrum. Our sessions are sensory-forward and intentionally slow — ideal if you want to decompress from stress, improve sleep architecture, or deepen meditation practice.</p>
      <div class="diagnostic-grid">
        <div class="card">
          <h3>Who benefits</h3>
          <ul>
            <li>Stressed professionals seeking grounding</li>
            <li>People curious about somatic reset</li>
            <li>Those craving a premium, guided rest experience</li>
          </ul>
        </div>
        <div class="card">
          <h3>Contraindications</h3>
          <p>Please consult your physician if you have: a history of seizures, implanted medical devices (e.g., pacemaker), uncontrolled psychiatric symptoms, or are pregnant and have concerns. Sounds are powerful — reach out at {{EMAIL}} with any medical questions before booking.</p>
        </div>
      </div>
    </section>

    <!-- PLAN: session flow -->
    <section class="plan wrap">
      <h2>Session flow — what to expect</h2>
      <ol class="flow">
        <li><strong>Arrival & grounding:</strong> Soft lighting, tea, and a brief orientation to posture and props.</li>
        <li><strong>Set intention:</strong> Short guided breathwork and optional journaling.</li>
        <li><strong>Main sound journey:</strong> A 45–60 minute tapestry of instruments — crystal bowls, monochord, and tuned chimes create evolving overtones.</li>
        <li><strong>Integration:</strong> Slow rewarming, light movement, and space to share or reflect.</li>
      </ol>
      <p class="muted">Each event is tailored; instrument selection and pacing vary to support different energetic needs.</p>
    </section>

    <!-- MICRO_HABITS: practical guide voice -->
    <section class="micro-habits wrap">
      <h2>Small practices to extend the effects</h2>
      <div class="grid-3">
        <div class="habit">
          <h4>Evening ritual</h4>
          <p>Dim lights for 30 minutes before bed; listen to low-volume humming or an app with binaural hums to prolong parasympathetic activation.</p>
        </div>
        <div class="habit">
          <h4>Morning check-in</h4>
          <p>Spend 3 minutes on belly breathing to anchor your nervous system each morning after the event.</p>
        </div>
        <div class="habit">
          <h4>Weekly embodiment</h4>
          <p>Wear comfortable clothes and practice 10 minutes of mindful movement to integrate somatic changes.</p>
        </div>
      </div>
    </section>

    <!-- PRICING: offerModel vip_day + pricing pack -->
    <section class="pricing wrap">
      <h2>Offerings & investments</h2>
      <p class="lead-muted">Practical packages for individual and group needs — VIP day coaching available.</p>
      <div class="pricing-grid">
        <div class="price-card">
          <h3>Community sound bath</h3>
          <p class="price">$35–$55</p>
          <p>Open events for groups. Includes 60 minutes of sound immersion and guidance. Bring a mat and an open mind.</p>
          <a class="btn" href="events.html">See calendar</a>
        </div>
        <div class="price-card">
          <h3>Private session — 1:1</h3>
          <p class="price">$180</p>
          <p>Tailored, private sound session with focused intention work. Includes pre-session consultation and follow-up notes.</p>
          <a class="btn" href="private-sessions.html">Book private</a>
        </div>
        <div class="price-card highlight">
          <h3>VIP day</h3>
          <p class="price">Custom pricing</p>
          <p>Half-day immersive experience for individuals or teams: deep reset, one-on-one coaching, and curated rituals — ideal for retreats or corporate wellness.</p>
          <a class="btn primary" href="book.html">Inquire about VIP day</a>
        </div>
      </div>
      <p class="muted">Rates may vary by location and group size. For corporate or extended retreats, contact {{EMAIL}}.</p>
    </section>

    <!-- CTA -->
    <section class="cta wrap">
      <div class="cta-inner">
        <div>
          <h2>Ready to reserve your place?</h2>
          <p>Space is intentionally limited to maintain an intimate, premium setting. Choose your way in — join a group or create a private experience.</p>
        </div>
        <div class="cta-actions">
          <a class="btn large primary" href="book.html">Book a session</a>
          <a class="btn large ghost" href="contact.html">Contact us</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="footer-brand">© <span id="year"></span> {{BUSINESS_NAME}} — {{CITY}}, {{STATE}}</div>
      <div class="footer-links">
        <a href="about.html">About</a>
        <a href="faq.html">FAQ</a>
        <a href="contact.html">Contact</a>
        <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>
      </div>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
