{"path":"assets/css/styles.css","content":"/* Base variables */
:root{
  --bg:#FAF5EF; --card:#FFFFFF; --accent:#8EC5FF; --accent-2:#FFD7B5; --text:#2B2B2B; --muted:#666; --accent-dark:#3B82F6;
  --radius:14px; --pad:24px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial; background:linear-gradient(180deg,var(--bg),#FFF); color:var(--text); -webkit-font-smoothing:antialiased}
.wrap{max-width:1100px;margin:0 auto;padding:28px}
.site-header{position:sticky;top:0;background:rgba(255,255,255,0.6);backdrop-filter:blur(6px);border-bottom:1px solid rgba(0,0,0,0.04)}
.site-header .wrap{display:flex;align-items:center;gap:16px}
.brand{font-weight:700;color:var(--accent-dark);text-decoration:none;font-size:1.1rem}
.nav{margin-left:auto;display:flex;gap:12px;align-items:center}
.nav a{color:var(--text);text-decoration:none;padding:8px 10px;border-radius:10px}
.nav a.cta{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#fff}
.nav-toggle{display:none;background:none;border:0;font-size:1.3rem}

.hero{padding:64px 0;background-repeat:no-repeat;background-size:cover;border-bottom:1px solid rgba(0,0,0,0.03)}
.hero-inner{display:grid:grid-template-columns:1fr 320px;align-items:stretch;grid-template-columns:1fr 340px;gap:28px}
.hero-copy h1{font-size:2.05rem;margin:0 0 12px}
.lead{color:var(--muted);margin:0 0 18px}
.hero-panel{background:linear-gradient(180deg,rgba(255,255,255,0.9),#fff);padding:18px;border-radius:12px;box-shadow:0 8px 30px rgba(23,31,76,0.06)}
.hero-panel .panel-top{font-size:0.85rem;color:var(--muted)}
.hero-panel .date{display:block;font-size:1.25rem;margin-top:8px}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;text-decoration:none;color:var(--text);border:1px solid rgba(0,0,0,0.05);background:#fff}
.btn.primary{background:linear-gradient(90deg,var(--accent-dark),#5BC0FF);color:white;border:0}
.btn.ghost{background:transparent;border:1px solid rgba(0,0,0,0.06)}
.btn.large{padding:14px 20px;font-weight:600}
.btn.small{padding:8px 10px;font-size:0.9rem}

.diagnostic{padding:36px 28px}
.diagnostic h2{margin-top:0}
.diagnostic-grid{display:flex;gap:20px}
.card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 6px 18px rgba(20,30,60,0.06);flex:1}
.card h3{margin-top:0}

.plan{padding:36px 28px}
.flow{margin:12px 0;padding-left:18px}
.flow li{margin:8px 0}
.muted{color:var(--muted);font-size:0.95rem}

.micro-habits{padding:36px 28px}
.grid-3{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px}
.habit{background:linear-gradient(180deg,#fff,#FBFBFF);padding:14px;border-radius:12px}

.pricing{padding:36px 28px}
.pricing-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px}
.price-card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 10px 30px rgba(30,40,80,0.05)}
.price-card.highlight{border:2px solid rgba(139,92,246,0.06);box-shadow:0 20px 40px rgba(124,58,237,0.06)}
.price{font-weight:700;font-size:1.25rem;margin:8px 0}

.cta{padding:34px 28px;background:linear-gradient(180deg,rgba(142,197,255,0.09),rgba(255,215,181,0.06));border-top:1px dashed rgba(0,0,0,0.03)}
.cta-inner{display:flex;align-items:center;justify-content:space-between;gap:20px}
.cta-actions{display:flex;gap:12px}

.site-footer{padding:22px 0;border-top:1px solid rgba(0,0,0,0.03);background:transparent}
.footer-links{display:flex;gap:12px}
.footer-links a{color:var(--muted);text-decoration:none}

/* Responsive */
@media (max-width:900px){
  .hero-inner{grid-template-columns:1fr;}
  .nav{display:none}
  .nav-toggle{display:block;margin-left:auto}
  .cta-inner{flex-direction:column;align-items:flex-start}
  .wrap{padding:18px}
  .diagnostic-grid{flex-direction:column}
}

/* Decorative wave using SVG mask */
.hero:after{content:"";position:absolute;left:0;right:0;height:220px;background:linear-gradient(180deg,rgba(255,255,255,0),#fff);pointer-events:none;transform:translateY(40px)}

/* Accessibility focus */
a:focus{outline:3px solid rgba(124,58,237,0.2);outline-offset:3px}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // small interactions: nav toggle, insert year, simple event detail modal
  document.addEventListener('DOMContentLoaded',function(){
    var btn=document.querySelector('.nav-toggle');
    var nav=document.querySelector('.nav');
    if(btn){btn.addEventListener('click',function(){nav.style.display = nav.style.display === 'flex' ? 'none' : 'flex';});}

    var y=document.getElementById('year'); if(y){y.textContent=(new Date()).getFullYear();}

    // Event panel click to open events page
    var nextPanel=document.querySelector('.hero-panel .btn');
    if(nextPanel){nextPanel.addEventListener('click',function(e){
      // simple ripple effect
      var el=e.currentTarget; var r=document.createElement('span'); r.className='ripple'; r.style.position='absolute'; r.style.borderRadius='50%'; r.style.background='rgba(255,255,255,0.3)'; r.style.width='120px'; r.style.height='120px'; r.style.left='10px'; r.style.top='10px'; el.style.position='relative'; el.appendChild(r);
      setTimeout(function(){try{el.removeChild(r);}catch(e){}},600);
    });}

    // Accessibility: smooth scroll for internal links
    document.querySelectorAll('a[href^="#"]').forEach(function(a){
      a.addEventListener('click',function(e){e.preventDefault();var id=this.getAttribute('href').slice(1);var el=document.getElementById(id); if(el) el.scrollIntoView({behavior:'smooth'});});
    });
  });
})();"} 
